{"t":"node","id":"media","product":"oss","label":"Media storage","group":"sg","why":"Stores raw recordings, thumbnails and VOD assets."}
{"t":"edge","id":"e-live-media","from":"live","to":"media","label":"record"}
{"t":"edge","id":"e-vod-media","from":"vod","to":"media","label":"store"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects platform logs for monitoring and alerting."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
